import {FOOD_BREAD_IDS,FOOD_IDS,FOOD_DRINKS,FOOD_DRINK_IDS} from '../state/food-catalog.js';
import {cafeFoodBag} from '../state/cafe-food.js';
import {materialBag} from '../state/gathering.js';
export const CAFE_DRINK_MENU=Object.freeze(['americano','latte','appleJuice']);
export const FOOD_LABELS=Object.freeze({milkRoll:'우유빵',croissant:'크루아상',miniCake:'작은 케이크',americano:'아메리카노',latte:'카페라테',appleJuice:'사과주스',strawberryJuice:'딸기주스',peachJuice:'복숭아주스',pearJuice:'배주스',mandarinJuice:'귤주스'});
export const DINING_CONTACT=.95,DINING_DURATION=2.5;
const copy=a=>a?{...a}:null;
/** Scene-scoped orchestration only. The existing root transact owns every durable write.
 * No timers, root transforms, ActivitySession mutations, or global modal API. */
export function createCafeFoodController({getProgress,transact,canSave=()=>true,getRoom,getSceneEpoch,getSupport,getActivity=()=>null,isAllowed=()=>true,presentation=null,getOrderSite=null,createDiningView=()=>null,onChange=()=>{},getEnabledDrinks=()=>CAFE_DRINK_MENU,reduced=false}){
 let operation=null,opened=false,mode=null,notice='',serial=0,paused=false,disposed=false;const shared=new Set();
 const supportNow=()=>getSupport()??null;
 const supported=(floor,captured=null)=>{const s=supportNow();return !!s&&!s.airborne&&s.surface===floor&&(!captured||captured.supportY===null||Number.isFinite(s.supportY)&&Math.abs(s.supportY-captured.supportY)<.001);};
 const supportSnapshot=()=>{const s=supportNow();return s?{surface:s.surface??null,supportY:Number.isFinite(s.supportY)?s.supportY:null}:null;};
 const sceneToken=()=>({room:getRoom(),epoch:getSceneEpoch()});
 const sameRoomScene=t=>!disposed&&getRoom()===t.room&&getSceneEpoch()===t.epoch;
 const sameScene=t=>t?.room==='bakeryCafe'&&sameRoomScene(t);
 const allowed=()=>!paused&&isAllowed();
 const seated=()=>{const a=getActivity(),t=a?.target;return a?.state==='active'&&t?.seating&&t.floor==='floor2'&&t.id?.startsWith('bakeryCafe.chair-')?a:null;};
 const sameSeat=o=>{const a=seated();return !!a&&a.token===o.seatToken;};
 const defaultOrderSite=()=>({id:'bakeryCafe.order-drink',roomId:'bakeryCafe',surface:'floor2',presentation,drinkIds:null});
 const currentOrderSite=()=>{let site=null;try{site=typeof getOrderSite==='function'?getOrderSite():null;}catch{return null;}return site??(getRoom()==='bakeryCafe'?defaultOrderSite():null);};
 const presenterFor=site=>site?.presentation??presentation;
 const siteShapeOk=site=>site?.id==='bakeryCafe.order-drink'&&site.roomId==='bakeryCafe'&&site.surface==='floor2'||site?.id==='courtyard.traveler-counter'&&site.roomId==='courtyard'&&site.surface==='ground';
 const menuFor=site=>{if(!site)return[];const available=getEnabledDrinks()??CAFE_DRINK_MENU,allowedIds=site.id==='courtyard.traveler-counter'?CAFE_DRINK_MENU:Array.isArray(site.drinkIds)?site.drinkIds:available;return available.filter(id=>FOOD_DRINK_IDS.includes(id)&&allowedIds.includes(id));};
 const siteAvailable=(site,{support=null,requireCurrent=true}={})=>{if(!siteShapeOk(site)||site.roomId!==getRoom()||!supported(site.surface,support)||typeof presenterFor(site)?.begin!=='function'||typeof presenterFor(site)?.ready!=='function'||!menuFor(site).length)return false;try{return !requireCurrent||typeof site.isCurrent!=='function'||site.isCurrent()===true;}catch{return false;}};
 const siteMatches=o=>{const now=currentOrderSite();return !!now&&siteShapeOk(now)&&now.id===o.site.id&&now.roomId===o.site.roomId&&now.surface===o.site.surface&&presenterFor(now)===o.presentation&&menuFor(now).join('|')===o.site.drinkIds.join('|')&&sameRoomScene(o.scene)&&supported(o.floor,o.support)&&siteAvailable(now,{support:o.support});};
 const valid=o=>o.kind==='order'?siteMatches(o):sameScene(o.scene)&&supported(o.floor)&&(o.kind!=='dine'||sameSeat(o));
 const notify=()=>onChange(api.snapshot());
 function cancel(reason='cancel'){const o=operation;operation=null;if(o){o.abort?.abort();o.view?.dispose();if(o.kind==='order')o.presentation?.cancel?.(o.id);o.consumption?.cancel();}if(reason==='scene'||reason==='pagehide'||reason==='disposed'||reason==='stand'){opened=false;mode=null;for(const s of [...shared])s.cancel();}notify();return !!o;}
 function fail(o,message){if(operation!==o)return false;o.phase='failed';notice=message;notify();return false;}
 function fresh(kind,floor,action,room='bakeryCafe'){if(disposed||operation&&!['done','failed'].includes(operation.phase)||getRoom()!==room||!sameRoomScene(sceneToken())||!supported(floor)||!allowed()||!canSave())return null;cancel();const o={id:'cafe-food-'+(++serial),kind,floor,scene:sceneToken(),action:Object.freeze(action),elapsed:0,phase:'preparing'};operation=o;notice='';return o;}
 function armConsumption(itemId,{recipientToken,isCurrent=()=>true}={}){const p=getProgress();if(!FOOD_IDS.includes(itemId)||!p.cafeFood||cafeFoodBag(p)[itemId]<1||!canSave()||!allowed()||getRoom()!=='bakeryCafe'||!supported('floor2'))return null;const scene=sceneToken(),action=Object.freeze({type:'FOOD_CONSUME',itemId,expectedConsumed:p.cafeFood.consumed[itemId],expectedRevision:p.revision});let alive=true,attempted=false,consumed=false;
  const current=()=>alive&&sameScene(scene)&&supported('floor2')&&isCurrent(recipientToken);
  const s={contact(){if(!current()||!allowed()||!canSave())return false;if(consumed)return true;if(attempted)return false;attempted=true;consumed=transact(action)===true;return consumed;},retry(){if(!current()||consumed||!attempted||!allowed()||!canSave())return false;attempted=false;return true;},cancel(){if(!alive)return;alive=false;shared.delete(s);},snapshot:()=>({itemId,recipientToken,attempted,consumed,alive,action:copy(action)})};shared.add(s);return s;
 }
 const api={
  open(next){if(disposed||!['pack','order','dine','pouch'].includes(next)||next!=='order'&&getRoom()!=='bakeryCafe'||next==='dine'&&!seated()||next==='pack'&&!supported('floor1')||next==='order'&&!siteAvailable(currentOrderSite()))return false;opened=true;mode=next;notice='';notify();return true;},
  close(){cancel();opened=false;mode=null;notify();},cancel,armConsumption,
  pack(recipeId){const p=getProgress();if(!FOOD_BREAD_IDS.includes(recipeId)||!p.cafeFood||p.village.cafe.stock[recipeId]<1)return false;const c=p.village.cafe,o=fresh('pack','floor1',{type:'FOOD_PACK_BREAD',recipeId,expectedPacked:p.cafeFood.packed[recipeId],expectedStock:c.stock[recipeId],expectedQualityStock:c.qualityStock[recipeId],expectedRevision:p.revision});if(!o)return false;opened=true;mode='pack';notify();return true;},
  order(recipeId){const p=getProgress(),site=currentOrderSite(),drinks=menuFor(site),provider=presenterFor(site);const recipe=FOOD_DRINKS[recipeId];if(!FOOD_DRINK_IDS.includes(recipeId)||!drinks.includes(recipeId)||!p.cafeFood||!provider||recipe.material&&materialBag(p)[recipe.material]<recipe.cost||!siteAvailable(site))return false;const support=supportSnapshot(),o=fresh('order',site.surface,{type:'FOOD_MAKE_DRINK',recipeId,expectedMade:p.cafeFood.made[recipeId],expectedRevision:p.revision},site.roomId);if(!o)return false;const latest=currentOrderSite();if(!siteAvailable(latest,{support})||latest.id!==site.id||presenterFor(latest)!==provider){cancel();return false;}o.site={id:site.id,roomId:site.roomId,surface:site.surface,drinkIds:drinks,token:site.token??null};o.support=support;o.presentation=provider;o.abort=new AbortController();o.loaded=false;opened=true;mode='order';try{Promise.resolve(provider.begin({sessionId:o.id,recipeId,signal:o.abort.signal})).then(result=>{if(operation!==o||!valid(o)||o.abort.signal.aborted){provider.cancel?.(o.id);return;}if(result===false)fail(o,site.roomId==='courtyard'?'음료를 준비하지 못했어요. 재료는 그대로예요':'코알라가 음료를 준비하지 못했어요. 재료는 그대로예요');else{o.loaded=true;notify();}},()=>{if(operation===o)fail(o,'음료를 준비하지 못했어요. 재료는 그대로예요');});}catch{fail(o,'음료를 준비하지 못했어요. 재료는 그대로예요');}notify();return true;},
  collect(){const o=operation;if(!o||!['pack','order'].includes(o.kind)||o.phase!=='ready'||o.kind==='order'&&!o.presentation.ready(o.id)||!valid(o)||!allowed()||!canSave())return false;o.phase='committing';if(!transact(o.action))return fail(o,'저장하지 못해 받지 않았어요. 저장 안내를 확인해 주세요');o.phase='done';if(o.kind==='order')o.presentation.received?.(o.id);notice=FOOD_LABELS[o.action.recipeId]+'을 음식주머니에 넣었어요';notify();return true;},
  eat(itemId){if(!seated()||!FOOD_IDS.includes(itemId))return false;const p=getProgress();if(!p.cafeFood||cafeFoodBag(p)[itemId]<1)return false;const a=seated(),o=fresh('dine','floor2',{});if(!o)return false;o.itemId=itemId;o.seatToken=a.token;o.consumption=armConsumption(itemId,{recipientToken:a.token,isCurrent:()=>operation===o&&sameSeat(o)});if(!o.consumption){cancel();return false;}o.action=Object.freeze(o.consumption.snapshot().action);try{o.view=createDiningView({itemId,seat:a.target,reduced});}catch{cancel();notice='음식을 놓지 못했어요. 음식은 그대로예요';notify();return false;}o.phase='eating';opened=true;mode='dine';o.view?.update({elapsed:0,consumed:false,phase:o.phase});notify();return true;},
  retry(){const o=operation;if(!o||o.phase!=='failed'||!valid(o)||!allowed()||!canSave())return false;if(o.kind==='dine'){if(!o.consumption.retry())return false;o.elapsed=0;o.phase='eating';notice='';notify();return true;}if(o.kind==='pack'||o.kind==='order'){if(o.kind==='order'&&(!o.loaded||!o.presentation.ready(o.id)))return false;o.phase='ready';notice='';notify();return api.collect();}return false;},
  suspend(reason='blur'){if(['pagehide','scene','map','modal','transition'].includes(reason)){cancel(reason==='pagehide'?'pagehide':'scene');return;}paused=true;notify();},
  resume(){paused=false;notify();},
  tick(dt){const o=operation;if(!o)return;if(!valid(o)){cancel('scene');return;}if(!allowed()||!canSave())return;if(!Number.isFinite(dt)||dt<=0)return;const step=Math.min(.05,dt);if(o.kind==='order'){o.presentation.tick?.(step,{paused:false});if(o.loaded&&o.phase==='preparing'&&o.presentation.ready(o.id)){o.phase='ready';notify();}return;}if(o.kind==='pack'){if(o.phase==='preparing'){o.elapsed+=step;if(o.elapsed>=.65){o.phase='ready';notify();}}return;}if(o.phase!=='eating')return;const prior=o.elapsed;o.elapsed=Math.min(DINING_DURATION,o.elapsed+step);if(prior<DINING_CONTACT&&o.elapsed>=DINING_CONTACT){o.view?.update({elapsed:DINING_CONTACT,consumed:false,phase:'contact'});if(!o.consumption.contact()){o.elapsed=DINING_CONTACT;fail(o,'저장하지 못해 먹지 않았어요. 음식은 그대로예요');o.view?.update({elapsed:0,consumed:false,phase:'failed'});return;}}const consumed=o.consumption.snapshot().consumed;o.view?.update({elapsed:o.elapsed,consumed,phase:o.phase});if(o.elapsed>=DINING_DURATION){o.phase='done';notice=FOOD_BREAD_IDS.includes(o.itemId)?'빵 한 개를 먹었어요':'음료 한 잔을 마셨어요';notify();}},
  snapshot(){const p=getProgress(),o=operation,site=currentOrderSite(),available=siteAvailable(site);return {open:opened,mode,notice,paused,readOnly:!canSave(),seated:!!seated(),seatId:seated()?.target.id??null,orderSiteId:available?site.id:null,enabledDrinks:menuFor(site),materials:materialBag(p),bag:p.cafeFood?cafeFoodBag(p):{},stock:{...p.village.cafe.stock},apples:materialBag(p).apple,operation:o?{id:o.id,kind:o.kind,phase:o.phase,itemId:o.itemId??o.action.recipeId,elapsed:o.elapsed,consumed:o.consumption?.snapshot().consumed??false,siteId:o.site?.id??null,action:copy(o.action)}:null};},
  get blocksAutomaticDiscovery(){return operation?.kind==='dine'&&['eating','failed'].includes(operation.phase)&&!operation.consumption?.snapshot().consumed;},
  get ownsArms(){return operation?.kind==='dine'&&!!operation.view;},get busy(){return opened||!!operation&&operation.phase!=='done';},
  dispose(){if(disposed)return;cancel('disposed');disposed=true;presentation?.dispose?.();}
 };return api;
}
